const datos = pm.response.json();
pm.test('Historial del intento finalizado', () => {
  pm.expect(datos).to.be.an('array').with.lengthOf(1);
  const entrada = datos[0];
  pm.expect(entrada.participacion.idIntento).to.eql(pm.environment.get('attemptId'));
  pm.expect(entrada.participacion.idSesion).to.eql(pm.environment.get('sessionId'));
  pm.expect(entrada.participacion.idEstudiante).to.eql(pm.environment.get('studentId'));
  pm.expect(entrada.participacion.estado).to.eql('FINALIZADO');
  pm.expect(entrada.participacion.respuestas[pm.environment.get('questionId')]).to.eql(pm.environment.get('optionId'));
});
pm.test('Reporte conserva calificación y retroalimentación', () => {
  pm.expect(Number(datos[0].resultado.calificacion)).to.eql(5);
  pm.expect(datos[0].resultado.detalles).to.have.lengthOf(1);
  const detalle = datos[0].resultado.detalles[0];
  pm.expect(detalle.idPregunta).to.eql(pm.environment.get('questionId'));
  pm.expect(detalle.idOpcion).to.eql(pm.environment.get('optionId'));
  pm.expect(detalle.correcta).to.eql(true);
  pm.expect(detalle.contestada).to.eql(true);
  pm.expect(detalle.retroalimentacion).to.be.a('string').and.not.empty;
});
pm.test('Sin valoraciones iniciales', () => pm.expect(datos[0].valoracionesGenerales).to.eql([]));

