const valoracion = pm.response.json();
pm.test('Identidad y contenido de valoración', () => {
  pm.expect(valoracion.id).to.match(/^[0-9a-f-]{36}$/i);
  pm.expect(valoracion.idIntento).to.eql(pm.environment.get('attemptId'));
  pm.expect(valoracion.idDocente).to.eql(pm.environment.get('teacherId'));
  pm.expect(valoracion.mensaje).to.eql("Buen análisis del caso y elección justificada de la respuesta.");
  pm.expect(Number.isNaN(Date.parse(valoracion.fecha))).to.eql(false);
});
pm.environment.set('valuationId', valoracion.id);

